const headers = $json.headers || {};
const body = $json.body || {};
const query = $json.query || {};
const sessionKey = headers['x-builder-key'] || headers['X-Builder-Key'] || body.sessionKey || query.sessionKey || null;
const origin = headers['x-foundry-origin'] || headers['X-Foundry-Origin'] || body.origin || query.origin || '';
if (!sessionKey) return [{ json: { authorized: false, error: 'NO_SESSION_KEY', message: 'Missing session key.', requiresAuth: true } }];
if (sessionKey.length !== 32 || !/^[a-f0-9]{32}$/.test(sessionKey)) return [{ json: { authorized: false, error: 'INVALID_SESSION_FORMAT', message: 'Invalid session key format.', requiresAuth: true } }];
return [{ json: { ...($json), sessionKey, requestOrigin: origin, _needsValidation: true } }];

const input = $('Session Validation Node').first().json;
const sessions = $input.all().map(i => i.json);
const sessionData = sessions && sessions.length > 0 ? sessions[0] : null;
if (!sessionData || !sessionData.key) return [{ json: { authorized: false, error: 'SESSION_NOT_FOUND', message: 'Session expired or invalid.', requiresAuth: true } }];
const now = new Date();
const expiresAt = new Date(sessionData.expires_at);
if (expiresAt < now) return [{ json: { authorized: false, error: 'SESSION_EXPIRED', message: 'Your session has expired.', requiresAuth: true } }];
const isSuperuser = sessionData.superuser === true;
const tier = sessionData.tier ? String(sessionData.tier).trim() : '';
return [{ json: { authorized: true, sessionEmail: sessionData.email, sessionTier: tier, sessionIsSuperuser: isSuperuser, sessionKey: sessionData.key, ...input } }];

const error = $json.error || 'UNAUTHORIZED';
const message = $json.message || 'You are not authorized to access this feature.';
const requiresAuth = $json.requiresAuth === true;
const rateLimitExceeded = $json.rateLimitExceeded === true;
return [{ json: { ok: false, error, message, requiresAuth, rateLimitExceeded, ...(rateLimitExceeded ? { currentUsage: $json.currentUsage, limit: $json.limit, tier: $json.tier, resetDate: $json.resetDate, upgradeUrl: $json.upgradeUrl } : {}), authUrl: requiresAuth ? 'https://foundryrelay.dedicated2.com/webhook/oauth/patreon/login' : undefined } }];

const PERSPECTIVES = {"top-down":"flat top-down orthographic floor plan seen from directly overhead, like a satellite view from far above. Only the top surfaces of walls, furniture, and objects are visible, and nothing has visible height or sides. Walls are flat strips, never showing their inner or outer faces. Tables read as flat circles and rectangles. Shadows are short and fall straight down","isometric":"isometric view at a 30 degree angle, 2:1 isometric projection, walls and objects shown from above at an angle","three-quarter":"three-quarter overhead view, camera tilted slightly so the fronts of walls and objects are visible, no horizon"};
const TOP_DOWN_VARIANTS = {"plan":"orthographic floor plan seen from directly overhead, like an architect's plan drawn in full color. Only the top surfaces of walls, furniture, and objects are visible. Walls are flat bands with no visible height or faces. Shadows are short and fall straight down","sat":"satellite view from far above, looking straight down, so nothing has visible height or sides. Tables read as flat circles and rectangles, chairs as small squares, and walls as flat strips","previous":"flat top-down orthographic view with the camera pointing straight down at 90 degrees, like a classic virtual tabletop battle map. Walls are flat thick outlines seen only from above, with no wall faces or sides of furniture visible. No tilt, no depth, no horizon, no vanishing point","combo":"orthographic floor plan seen from directly overhead, like a satellite view from far above. Only the top surfaces of walls, furniture, and objects are visible, and nothing has visible height or sides. Walls are flat strips, never showing their inner or outer faces. Tables read as flat circles and rectangles. Shadows are short and fall straight down"};
const MOODS = {"day":"bright daylight","dusk":"warm dusk light with long shadows","night":"night time, dark with warm light from lamps, torches, and other light sources"};
const DIALS = {"detail":{"label":"Detail","stage":"mockup","levels":["simple and clean, with large plain areas and only the key features","lightly detailed, with simple textures","highly detailed","very highly detailed, with rich textures on every surface","extremely intricate, with fine texture and small details everywhere"]},"clutter":{"label":"Props","stage":"mockup","levels":["almost empty, with only essential furniture","sparse props",null,"plenty of props and furnishings","crowded with props, debris, and small objects, while keeping clear floor space to walk on"]},"wear":{"label":"Wear","stage":"mockup","levels":["everything pristine and brand new","everything clean and well kept",null,"surfaces worn, dirty, and cracked","ruined, broken, and overgrown surroundings"]},"color":{"label":"Color","stage":"filter","levels":[0.35,0.7,1,1.3,1.6]},"tint":{"label":"Color temperature","stage":"filter","levels":[-1,-0.5,0,0.5,1]},"contrast":{"label":"Lighting contrast","stage":"filter","levels":[0.75,0.88,1,1.15,1.3]},"sharpness":{"label":"Sharpness","stage":"filter","levels":[-1,-0.5,0,0.6,1.2]}};
const SIZE_BOOST = {"indoor":2.2,"outdoor":1.15};
const OUTDOOR = new RegExp("\\b(town|village|city|street|road|forest|alley|market|camp|wasteland|highway|courtyard|bridge|field|jungle|outpost|main deck|square)\\b", "i");
const ASPECTS = [["1:1",1],["4:3",1.3333333333333333],["3:4",0.75],["3:2",1.5],["2:3",0.6666666666666666],["16:9",1.7777777777777777],["9:16",0.5625]];
function checkDials(dials) {
  for (const [k, v] of Object.entries(dials)) {
    if (!DIALS[k]) throw new Error(`Unknown dial "${k}"`);
    if (!Number.isInteger(v) || v < 1 || v > 5) throw new Error(`Dial "${k}" must be a whole number from 1 to 5`);
  }
}
function dialPhrases(dials = {}) {
  checkDials(dials);
  return Object.entries(DIALS).filter(([, d]) => d.stage === 'mockup').map(([k, d]) => d.levels[(dials[k] ?? 3) - 1]).filter(Boolean);
}
function cap(s) {
  return s.charAt(0).toUpperCase() + s.slice(1);
}
function sizeBoost(p) {
  if (typeof p.sizeBoost === 'number') return p.sizeBoost;
  const setting = p.setting || (OUTDOOR.test(p.description) ? 'outdoor' : 'indoor');
  return SIZE_BOOST[setting] ?? 1;
}
function buildPrompt(p) {
  const view = p.view ? TOP_DOWN_VARIANTS[p.view] : PERSPECTIVES[p.perspective];
  if (!view) throw new Error(`Unknown perspective "${p.perspective}"`);
  const mood = MOODS[p.mood] || p.mood;
  const [w, h] = p.squares;
  const boost = sizeBoost(p);
  return [
    `Tabletop RPG battle map, ${view}.`,
    `${cap(p.genre)} setting, ${p.style} art style, ${mood}.`,
    `Scene: ${p.description}.`,
    // Dark water came out as a flat black hole on night maps (Nov 3 crypt test).
    ...(/water|river|lake|pond|pool|flood|sea|stream|canal|moat|swamp|marsh/i.test(p.description) ? ['Draw any water, even water described as dark or black, in deep teal or green-blue with visible ripples, reflections of nearby lights, and the floor or stones showing through where it is shallow. Never draw water as a flat black area.'] : []),
    `The map covers an area of ${Math.round(w * boost)} by ${Math.round(h * boost)} five-foot squares, so a doorway is about one square wide and a person fits in one square.`,
    `Look: ${[...dialPhrases(p.dials), 'crisp textures'].join('; ')}.`,
    'Clear readable layout, the whole area fills the frame edge to edge.',
    'Do not draw any grid lines, text, labels, legend, compass, border, frame, or watermark. No people or creatures.',
  ].join(' ');
}
function pickAspect([w, h]) {
  const target = w / h;
  let best = ASPECTS[0];
  for (const a of ASPECTS) {
    if (Math.abs(Math.log(a[1] / target)) < Math.abs(Math.log(best[1] / target))) best = a;
  }
  return best[0];
}
function finalPrompt(p) {
  return [
    'The attached image is a rough layout mockup. Redraw it as a finished battle map.',
    'Keep the same layout: room shapes, walls, doors, paths, and where every feature sits, and keep the same camera angle.',
    'Ignore and remove any grid lines, text, or labels in the mockup.',
    ...(p.perspective === 'top-down' ? ['If the mockup is tilted or shows the sides of walls, flatten it into a true straight-down view.'] : []),
    buildPrompt(p),
  ].join(' ');
}
const body = $json.body || {};
try {
  const action = body.action;
  if (!['mockups','final'].includes(action)) throw new Error('Unknown map action.');
  const map = body.map;
  if (!map || typeof map !== 'object') throw new Error('A map is required.');
  for (const key of ['description','perspective','genre','style','mood']) if (typeof map[key] !== 'string' || !map[key].trim()) throw new Error('Map '+key+' is required.');
  if (!Array.isArray(map.squares) || map.squares.length !== 2 || !map.squares.every(n => Number.isInteger(n) && n > 0)) throw new Error('Map squares must be two positive whole numbers.');
  if (map.dials != null && (typeof map.dials !== 'object' || Array.isArray(map.dials))) throw new Error('Map dials must be an object.');
  if (map.setting != null && !['indoor','outdoor'].includes(map.setting)) throw new Error('Unknown map setting.');
  if (map.view != null && !TOP_DOWN_VARIANTS[map.view]) throw new Error('Unknown map view.');
  const aspect = pickAspect(map.squares);
  let mockup = null;
  if (action === 'final') {
    mockup = body.mockup;
    if (!mockup || typeof mockup.b64 !== 'string' || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(mockup.b64) || !mockup.b64.length) throw new Error('A base64 mockup image is required.');
    if (mockup.mediaType != null && !/^image\/[a-z0-9.+-]+$/i.test(mockup.mediaType)) throw new Error('Invalid mockup media type.');
    if (body.units != null && !['imperial','metric'].includes(body.units)) throw new Error('Unknown unit system.');
    if (body.square != null && !(Number.isFinite(body.square) && body.square > 0)) throw new Error('Square size must be positive.');
  }
  const prompt = action === 'mockups' ? 'Quick rough mockup for layout only. ' + buildPrompt(map) : finalPrompt(map);
  return [{json:{...$json,_map:{action,cost:action==='mockups'?3:6,map,mockup:mockup?{b64:mockup.b64,mediaType:mockup.mediaType||'image/png'}:null,units:body.units||'imperial',square:body.square,prompt,aspect,startedAt:Date.now()}}}];
} catch (e) { return [{json:{ok:false,error:'BAD_REQUEST',message:e.message,usesCharged:0}}]; }

const TIER_LIMITS={'free':3,'no tier':3,'none':3,'':3,'supporter':25,'professional':100,'premium':200,'superuser':999999};
const email=($json.sessionEmail||'').toLowerCase().trim();
const sessionKey=($json.sessionKey||'').trim();
const lookupKey=email||sessionKey;
if(!lookupKey)throw new Error('No email or session key found.');
const sessionTier=($json.sessionTier||'').toLowerCase().trim();
const tier=$json.sessionIsSuperuser===true?'superuser':sessionTier;
const monthlyLimit=Object.prototype.hasOwnProperty.call(TIER_LIMITS,tier)?TIER_LIMITS[tier]:3;
const currentMonth=new Date().toISOString().substring(0,7);
return [{json:{...$json,sessionTier:tier,_rateLimitCheck:{sessionKey:lookupKey+'::'+currentMonth,email:lookupKey,currentMonth,monthlyLimit,tier}}}];

const originalData=$('Rate Limit: Prepare Check').first().json;
const rateLimitData=originalData._rateLimitCheck;
const cost=originalData._map.cost;
const usageData=$input.all().map(i=>i.json).find(r=>r?.session_key);
const currentCount=Number(usageData?.npc_count)||0;
if(currentCount+cost>rateLimitData.monthlyLimit){
  const resetDate=new Date();resetDate.setMonth(resetDate.getMonth()+1);resetDate.setDate(1);resetDate.setHours(0,0,0,0);
  return [{json:{ok:false,rateLimitExceeded:true,error:'RATE_LIMIT_EXCEEDED',message:'A map '+(originalData._map.action==='mockups'?'mockups':'final map')+' costs '+cost+' uses. You have used '+currentCount+' of your '+rateLimitData.monthlyLimit+' monthly uses.',currentUsage:currentCount,limit:rateLimitData.monthlyLimit,tier:rateLimitData.tier,resetDate:resetDate.toISOString(),upgradeUrl:'https://www.patreon.com/c/CelestiaTools/membership'}}];
}
return [{json:{...originalData,_rateLimitCheck:{...rateLimitData,currentCount,usageRecordExists:!!usageData,usageRecordId:usageData?.id||null}}}];

const prep=$('Rate Limit: Validate').first().json;
const {prompt,aspect}=prep._map;
return Array.from({length:4},()=>({json:{body:{n:1,model:'black-forest-labs/flux.2-klein-4b',prompt,aspect_ratio:aspect,resolution:'1K'}}}));

const prep=$('Rate Limit: Validate').first().json._map;
const responses=$input.all().map(i=>i.json);
const images=responses.flatMap(r=>(r.data||[]).filter(i=>i?.b64_json).map(i=>({b64:i.b64_json,mediaType:i.media_type||'image/png'})));
const costUsd=responses.reduce((sum,r)=>sum+(Number(r.usage?.cost)||0),0);
const failed=4-images.length;
return [{json:images.length?{ok:true,action:'mockups',images,failed,aspect:prep.aspect,prompt:prep.prompt,costUsd,ms:Date.now()-prep.startedAt}:{ok:false,error:'GENERATION_FAILED',message:'No mockup images were generated.',usesCharged:0}}];

const prep=$('Rate Limit: Validate').first().json._map;
const {prompt,aspect,mockup}=prep;
return [{json:{body:{n:1,model:'google/gemini-3.1-flash-image',prompt,aspect_ratio:aspect,resolution:'2K',input_references:[{type:'image_url',image_url:{url:'data:'+mockup.mediaType+';base64,'+mockup.b64}}]},costUsd:0}}];

const prior = $('Final: Build Request').first().json;
const raw = $json || {};
const img = raw.data?.[0];
const image = img?.b64_json ? {b64:img.b64_json,mediaType:img.media_type||'image/png'} : null;
const costUsd = (prior.costUsd||0)+(Number(raw.usage?.cost)||0);

return [{json:{...prior,image,costUsd,...(image?{}:{ok:false,error:'GENERATION_FAILED',message:'The image provider returned no image.',usesCharged:0})}}];

const CHECK_PROMPT = `You are checking an AI-generated tabletop RPG battle map before it goes into Foundry VTT, which adds its own grid.
Answer each question about the image:
grid: are there square or hex grid lines drawn over the map? Floor tiles, paving stones, deck planks, or floor grates that are part of the scenery do not count. Only a regular overlay of thin lines across the map counts, including faint ones.
text: is there any label, number, title, legend, scale bar, dimension, signature, or watermark? Writing that is part of the scene, such as a shop sign or a neon sign, does not count.
frame: is there a drawn decorative border, picture frame, parchment edge, or blueprint sheet around the map? The outer walls of a building or room do not count.
margin: is the map drawn on plain paper, parchment, or a white, grey, or light background, with that blank area showing around it? Dark empty space or rock outside the walls of an interior is normal and does not count. Give the share of the image that is such blank background, from 0 to 1.
Return JSON only: {"grid":true|false,"text":true|false,"frame":true|false,"margin":0.0,"notes":"one short sentence"}`;
function checkRequest(image) { return { model:'google/gemini-3.7-flash', response_format:{type:'json_object'}, usage:{include:true}, messages:[{role:'user',content:[{type:'text',text:CHECK_PROMPT},{type:'image_url',image_url:{url:'data:'+image.mediaType+';base64,'+image.b64}}]}] }; }
return [{json:{body:checkRequest($json.image)}}];

function mapDefects(raw, { perspective = 'top-down', maxMargin = 0.08 } = {}) {
  const reasons = ['grid', 'text', 'frame'].filter(k => raw[k] === true);
  if (perspective === 'top-down' && Number(raw.margin) > maxMargin) reasons.push('margin');
  return { retry: reasons.length > 0, reasons };
}
const prior=$('Final: Parse Image').first().json;
const response=$json||{};
let defects={retry:false,reasons:[]}, warning;
try { const raw=JSON.parse(String(response.choices?.[0]?.message?.content||'').trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '')); defects=mapDefects(raw,{perspective:$('Rate Limit: Validate').first().json._map.map.perspective}); } catch { warning='The map could not be checked.'; }
return [{json:{...prior,defects,warning,costUsd:prior.costUsd+(Number(response.usage?.cost)||0),retried:false}}];

const prep=$('Rate Limit: Validate').first().json._map;
const first=$('Final: Judge').first().json;
return [{json:{body:{n:1,model:'google/gemini-3.1-flash-image',prompt:prep.prompt,aspect_ratio:prep.aspect,resolution:'2K',input_references:[{type:'image_url',image_url:{url:'data:'+prep.mockup.mediaType+';base64,'+prep.mockup.b64}}]}}}];

