}
const prior=$('Final: Parse Retry').first().json;
const response=$json||{};
let defects=prior.defects, warning=prior.warning;
if(!prior.retryImageFailed) { try { const raw=JSON.parse(String(response.choices?.[0]?.message?.content||'').trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '')); defects=mapDefects(raw,{perspective:$('Rate Limit: Validate').first().json._map.map.perspective}); if(defects.retry) warning='The final map still has: '+defects.reasons.join(', ')+'.'; } catch { warning='The map could not be checked.'; } }
return [{json:{...prior,defects,warning,costUsd:prior.costUsd+(Number(response.usage?.cost)||0)}}];

const chosen=$json;
const SCALE_PROMPT=`This is a tabletop RPG battle map. Estimate the real-world size of the whole area shown in the image, edge to edge.
Use objects of known size as rulers: a single door is about 0.9 m wide, a chair about 0.5 m, a bed about 2 m long, a round tavern table about 1.2 m across, a cart about 3 m long, a person about 0.5 m across from above.
Measure at least three different objects, work out metres per pixel from each, and combine them.
Return JSON only: {"references":[{"object":"...","size_m":0.9,"share_of_width":0.03}],"width_m":<number>,"height_m":<number>}
share_of_width is how much of the image width the object spans.`;
const image=chosen.image;
const body={model:'google/gemini-3.7-flash',response_format:{type:'json_object'},usage:{include:true},messages:[{role:'user',content:[{type:'text',text:SCALE_PROMPT},{type:'image_url',image_url:{url:'data:'+image.mediaType+';base64,'+image.b64}}]}]};
return [{json:{body,chosen}},{json:{body,chosen}}];

const UNIT_SYSTEMS = {"imperial":{"units":"ft","square":5},"metric":{"units":"m","square":1.5}};
const FEET_PER_METRE = 3.28084;
function averageScale(a, b) {
  const valid = value => Number.isFinite(value?.width_m) && value.width_m > 0 && Number.isFinite(value?.height_m) && value.height_m > 0;
  const estimates = [a, b].filter(valid);
  if (!estimates.length) throw new Error('At least one valid size estimate is required.');
  return {
    width_m: estimates.reduce((sum, value) => sum + value.width_m, 0) / estimates.length,
    height_m: estimates.reduce((sum, value) => sum + value.height_m, 0) / estimates.length,
  };
}
function sceneScale({ width_m, height_m }, { system = 'imperial', square, gridPx = 100 } = {}) {
  if (!(width_m > 0 && height_m > 0)) throw new Error('The size estimate needs a positive width and height.');
  const u = UNIT_SYSTEMS[system];
  if (!u) throw new Error(`Unknown unit system "${system}"`);
  const size = square || u.square;
  const toUnits = m => (u.units === 'ft' ? m * FEET_PER_METRE : m);
  const squares = [Math.max(1, Math.round(toUnits(width_m) / size)), Math.max(1, Math.round(toUnits(height_m) / size))];
  return {
    squares,
    width: squares[0] * gridPx,
    height: squares[1] * gridPx,
    grid: { size: gridPx, distance: size, units: u.units },
  };
}
const prep=$('Rate Limit: Validate').first().json._map;
const chosen=$('Scale: Build Requests').first().json.chosen;
const responses=$input.all().map(i=>i.json);
const estimates=responses.map(r=>{try{return JSON.parse(String(r.choices?.[0]?.message?.content||'').trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, ''));}catch{return null;}}).filter(e=>e&&Number.isFinite(e.width_m)&&e.width_m>0&&Number.isFinite(e.height_m)&&e.height_m>0);
let measured,scene,warning=chosen.warning;
if(estimates.length){ const avg=averageScale(estimates[0],estimates[1]); measured={...avg,estimates}; scene=sceneScale(avg,{system:prep.units,square:prep.square}); }
else { const size=prep.square||(prep.units==='metric'?1.5:5); const units=prep.units==='metric'?'m':'ft'; const squares=prep.map.squares; measured={width_m:null,height_m:null,estimates:[]}; scene={squares,width:squares[0]*100,height:squares[1]*100,grid:{size:100,distance:size,units}}; warning=[warning,'Map size could not be measured; the requested squares were used.'].filter(Boolean).join(' '); }
const costUsd=chosen.costUsd+responses.reduce((sum,r)=>sum+(Number(r.usage?.cost)||0),0);
return [{json:{ok:true,action:'final',image:chosen.image,defects:chosen.defects,retried:chosen.retried,...(warning?{warning}:{}),measured,scene,costUsd,ms:Date.now()-prep.startedAt}}];

const rateLimitData=$('Rate Limit: Validate').first().json._rateLimitCheck;
const cost=$('Rate Limit: Validate').first().json._map.cost;
const now=new Date().toISOString();
return [{json:{session_key:rateLimitData.sessionKey,month:rateLimitData.currentMonth,npc_count:rateLimitData.currentCount+cost,last_created:now}}];

let payload;
try { payload=$('Scale: Combine').first().json; } catch {}
if(!payload?.ok) { try { payload=$('Mockups: Collect').first().json; } catch {} }
const cost=$('Rate Limit: Validate').first().json._map.cost;
return [{json:{...payload,usesCharged:cost}}];
